from __future__ import annotations


STABLE_OPERATOR_EXTENSION = r"""
<style>
.mon-shell{max-width:1500px;margin:0 auto}.mon-targetbar{display:grid;grid-template-columns:minmax(260px,440px) auto auto;gap:8px;margin:12px 0}.mon-targetbar input{height:35px;border:1px solid #999;padding:0 10px;font:12px Consolas,monospace}.mon-hero{display:grid;grid-template-columns:repeat(6,1fr);border-left:1px solid #c7c7c7;border-top:1px solid #c7c7c7;margin:14px 0}.mon-hero>div{padding:11px;border-right:1px solid #c7c7c7;border-bottom:1px solid #c7c7c7;min-height:68px}.mon-hero strong{display:block;font-size:17px;margin-top:5px}.mon-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.mon-panel{border:1px solid #c7c7c7;padding:13px;min-width:0}.mon-row{padding:8px 0;border-bottom:1px solid #ddd;font-size:10px;line-height:1.5}.mon-badge{display:inline-block;border:1px solid #111;padding:3px 6px;font-size:9px;font-weight:700;margin-right:5px}.mon-empty{font-size:10px;color:#666;padding:10px 0}.mon-reason{border-left:2px solid #111;padding:5px 8px;margin:5px 0;font-size:10px}.mon-watch{display:grid;grid-template-columns:repeat(5,1fr);border-left:1px solid #c7c7c7;border-top:1px solid #c7c7c7;margin:14px 0}.mon-watch>div{padding:12px;border-right:1px solid #c7c7c7;border-bottom:1px solid #c7c7c7;min-height:72px}.mon-watch strong{display:block;font-size:18px;margin-top:6px}.mon-problem{border:1px solid #c7c7c7;padding:12px;margin-bottom:9px}.mon-problem.bad{border-left:4px solid #111}.mon-problem .title{font-weight:800;font-size:12px}.mon-meta{font-size:10px;line-height:1.55;margin-top:7px}.mon-actions{display:flex;gap:5px;flex-wrap:wrap}.mon-target-table{max-height:430px}.mon-history{max-height:240px;overflow:auto}
@media(max-width:1050px){.mon-grid{grid-template-columns:1fr}.mon-hero{grid-template-columns:repeat(3,1fr)}.mon-targetbar{grid-template-columns:1fr}.mon-watch{grid-template-columns:repeat(2,1fr)}}
@media(max-width:650px){.mon-hero,.mon-watch{grid-template-columns:1fr 1fr}}
</style>
<script>
(()=>{
const E=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let lastTargets=0,lastWatch=0;
async function api(path){const r=await fetch(path,{cache:'no-store'});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(typeof d.detail==='string'?d.detail:JSON.stringify(d.detail||d));return d;}
function stat(label,value){return`<div><div class="label">${esc(label)}</div><strong>${esc(value)}</strong></div>`}
function list(values,empty='None observed'){if(!values||!values.length)return`<div class="mon-empty">${esc(empty)}</div>`;return values.map(v=>`<div class="mon-row">${esc(Array.isArray(v)?`${v[0]} · ${v[1]}`:v)}</div>`).join('')}
function inject(){
 if(E('view-investigation'))return;
 const nav=document.querySelector('nav'),main=document.querySelector('main'),system=nav?.querySelector('button.tab[data-view="system"]'),foot=main?.querySelector('.foot');if(!nav||!main)return;
 try{pages.investigation=['Investigation','Evidence-backed investigation of packet-observed IPs.'];pages.watchdog=['Watchdog','Live Windows MON runtime supervision.'];}catch{}
 for(const [view,label] of [['investigation','Investigation'],['watchdog','Watchdog']]){const b=document.createElement('button');b.className='tab';b.dataset.view=view;b.textContent=label;b.onclick=()=>{setView(view);if(view==='investigation')loadTargets();else loadWatchdog();};nav.insertBefore(b,system||null);}
 const holder=document.createElement('div');holder.innerHTML=`
 <div class="view" id="view-investigation"><section class="mon-shell"><div class="sectionhead"><div><h2>Investigation</h2><div class="small">MON accepts only IPs observed in the current TShark session. Unseen IPs are rejected; no fabricated safety or risk verdict is produced.</div></div></div><div class="mon-targetbar"><input id="investigationTarget" placeholder="Packet-observed IP"><button class="btn" id="investigationRun">Investigate</button><button class="btn" id="investigationRefresh">Refresh Targets</button></div><div class="mon-hero" id="investigationStats"></div><div class="mon-grid"><div class="mon-panel"><div class="label">Assessment</div><div id="investigationAssessment" class="mon-empty">Choose an observed target.</div><div class="label" style="margin-top:14px">Historical Metadata</div><div id="investigationHistory" class="mon-history"><div class="mon-empty">No target selected.</div></div></div><div class="mon-panel"><div class="label">Evidence Pivots</div><div id="investigationPivots" class="mon-empty">No target selected.</div></div></div><div class="mon-panel" style="margin-top:14px"><div class="label">Identity & Exposure</div><div id="investigationIdentity" class="mon-empty">Choose an observed IP to view passive identity and naming evidence.</div></div><div class="mon-panel" style="margin-top:14px"><div class="label">Current Packet-Observed Targets</div><div class="tablewrap mon-target-table"><table><thead><tr><th>IP</th><th>Name</th><th>Vendor</th><th>Class</th><th>Packets</th><th>Evidence</th><th></th></tr></thead><tbody id="investigationTargets"><tr><td colspan="7" class="muted">Loading…</td></tr></tbody></table></div></div></section></div>
 <div class="view" id="view-watchdog"><section class="mon-shell"><div class="sectionhead"><div><h2>Watchdog</h2><div class="small">Supervises the Windows adapter, monitoring session, TShark/Npcap capture process, event bus and analysis workers.</div></div><button class="btn" id="watchdogRefresh">Refresh</button></div><div class="mon-watch" id="watchdogStats"></div><div class="mon-grid"><div class="mon-panel"><div class="label">Runtime Diagnostics</div><div id="watchdogProblems" class="mon-empty">Loading…</div></div><div class="mon-panel"><div class="label">Security Conditions</div><div id="watchdogAnomalies" class="mon-empty">Loading…</div></div></div></section></div>`;
 while(holder.firstChild)main.insertBefore(holder.firstChild,foot||null);
 E('investigationRun').onclick=()=>runInvestigation(E('investigationTarget').value);E('investigationTarget').addEventListener('keydown',e=>{if(e.key==='Enter')runInvestigation(e.currentTarget.value)});E('investigationRefresh').onclick=()=>loadTargets(true);E('watchdogRefresh').onclick=()=>loadWatchdog(true);
 window.openInvestigation=target=>{target=String(target||'').trim();if(target)E('investigationTarget').value=target;setView('investigation');if(target)runInvestigation(target);};
 loadTargets(true);
}
async function loadTargets(force=false){if(!force&&Date.now()-lastTargets<2500)return;const body=E('investigationTargets');try{const d=await api('/api/v1/operator/targets'),rows=d.targets||[];lastTargets=Date.now();body.innerHTML=rows.map(x=>`<tr><td class="mono">${esc(x.ip)}</td><td>${esc(x.name||'—')}${x.name_source?`<br><span class="muted">${esc(x.name_source)}</span>`:''}</td><td>${esc(x.vendor||'—')}</td><td>${esc(x.classification||'—')}</td><td>${Number(x.packets||0).toLocaleString()}</td><td>${esc(x.evidence||'—')}</td><td><button class="btn" data-target="${esc(x.ip)}">Investigate</button></td></tr>`).join('')||'<tr><td colspan="7" class="muted">No packet-observed IP targets in this session yet.</td></tr>';body.querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>window.openInvestigation(b.dataset.target||''));}catch(err){body.innerHTML=`<tr><td colspan="6" class="muted">${esc(err.message)}</td></tr>`}}
async function runInvestigation(target){target=String(target||'').trim();if(!target)return;E('investigationAssessment').textContent='Correlating evidence…';try{const r=await api(`/api/v1/operator/investigate/${encodeURIComponent(target)}`),s=r.summary||{},risk=r.risk||{},h=r.history||{},id=r.identity||{},inds=r.security_indicators||[];E('investigationTarget').value=r.target||target;E('investigationStats').innerHTML=stat('Target',r.target||'—')+stat('Observed','YES')+stat('Assessment',String(risk.assessment||'OBSERVED').replaceAll('_',' '))+stat('Priority',risk.score===null||risk.score===undefined?'NO SCORE':`${Number(risk.score)}/100`)+stat('Flows',s.flow_count||0)+stat('Peers',s.peer_count||0);const reasons=risk.reasons||[];E('investigationAssessment').innerHTML=`<div class="mon-row"><span class="mon-badge">CURRENT PACKET EVIDENCE</span>${esc(risk.claim||'')}</div>`+(reasons.length?reasons.map(x=>`<div class="mon-reason">${esc(x)}</div>`).join(''):'<div class="mon-empty">No anomaly evidence is currently associated with this observed target.</div>')+(inds.length?'<div class="label" style="margin-top:12px">Security Indicators</div>'+inds.map(x=>`<div class="mon-problem bad"><div class="title">${esc(x.title||'Indicator')} · ${esc(x.severity||'INFO')} · confidence ${esc(x.confidence??'—')}%</div><div class="mon-meta">${esc(x.claim||x.evidence_class||'packet evidence')}</div></div>`).join(''):'');E('investigationPivots').innerHTML='<div class="label">Top Peers</div>'+list(s.top_peers)+'<div class="label" style="margin-top:10px">Top Services</div>'+list(s.top_services)+'<div class="label" style="margin-top:10px">Top Applications</div>'+list(s.top_applications)+`<div class="label" style="margin-top:10px">Evidence Counts</div><div class="mon-row">Alerts ${Number(s.alert_count||0)} · Incidents ${Number(s.incident_count||0)} · Packets ${Number(s.packets||0).toLocaleString()} · Bytes ${Number(s.bytes||0).toLocaleString()}</div>`;const hist=h.recent_events||[];E('investigationHistory').innerHTML=`<div class="mon-row">Retention: ${Number(h.retention_days||0)} days · Events: ${Number(h.event_count||0)} · Snapshots: ${Number(h.snapshot_count||0)}</div>`+(hist.map(x=>`<div class="mon-row"><b>${esc(x.kind||'EVENT')}</b> · ${esc(x.severity||'INFO')} · ${esc(x.timestamp||'')}</div>`).join('')||'<div class="mon-empty">No older metadata for this target yet.</div>');const names=Object.entries(id.hostname_sources||{}).map(([k,v])=>`${k}: ${v}`);E('investigationIdentity').innerHTML=Object.keys(id).length? `<div class="mon-row"><b>Hostname:</b> ${esc(id.hostname||'—')}<br><b>MAC:</b> ${esc(id.mac||'—')}<br><b>Vendor:</b> ${esc(id.vendor||'—')}<br><b>Role:</b> ${esc(id.role||'—')}<br><b>VLAN:</b> ${esc(id.vlan_id||'—')}<br><b>Stack hint:</b> ${esc(id.ip_stack_hint||'—')} <span class="muted">(${esc(id.ip_stack_hint_confidence||'')})</span><br><b>TTL / estimated hops:</b> ${esc(id.observed_ttl??'—')} / ${esc(id.estimated_hops??'—')}<br><b>First / last seen:</b> ${esc(id.first_seen||'—')} / ${esc(id.last_seen||'—')}</div><div class="label" style="margin-top:10px">Hostname Evidence</div>${list(names,'No passive hostname evidence yet')}<div class="label" style="margin-top:10px">Responding Services</div>${list(id.observed_services,'No TCP service response observed yet')}<div class="label" style="margin-top:10px">Top Protocols</div>${list(id.top_protocols)}<div class="label" style="margin-top:10px">Application / Domain Names</div>${list(id.top_application_names,'No DNS/TLS/HTTP names observed from this host')}</div>`:'<div class="mon-empty">This IP is packet-observed, but MON has not yet seen reliable passive naming or local-asset identity evidence for it.</div>';}catch(err){E('investigationStats').innerHTML='';E('investigationAssessment').innerHTML=`<div class="mon-problem bad"><div class="title">Investigation refused</div><div class="mon-meta">${esc(err.message)}</div></div>`;E('investigationPivots').innerHTML='<div class="mon-empty">No evidence report produced.</div>';E('investigationHistory').innerHTML='<div class="mon-empty">No history shown for an unverified target.</div>';E('investigationIdentity').innerHTML='<div class="mon-empty">No identity report produced.</div>';}}
async function loadWatchdog(force=false){if(!force&&Date.now()-lastWatch<2500)return;try{const d=await api('/api/v1/system/watchdog'),c=d.capture||{},diag=d.diagnostics||{},an=d.anomalies||{};lastWatch=Date.now();E('watchdogStats').innerHTML=stat('State',d.state||'UNKNOWN')+stat('Interface',d.interface||'—')+stat('Capture',c.state||'—')+stat('TShark PID',c.process_pid||'—')+stat('Packets',Number(c.packets||0).toLocaleString());const probs=diag.problems||[];E('watchdogProblems').innerHTML=probs.length?probs.map(p=>`<div class="mon-problem bad"><div class="title">${esc(p.problem||'Runtime problem')} · ${esc(p.severity||'INFO')}</div><div class="mon-meta"><b>Evidence:</b> ${esc(p.evidence||'—')}<br><b>Cause:</b> ${esc(p.cause||'—')}<br><b>Fix:</b> ${esc(p.fix||'—')}<br><b>Verify:</b> ${esc(p.verify||'—')}</div></div>`).join(''):'<div class="mon-problem"><div class="title">Runtime checks healthy</div><div class="mon-meta">Selected adapter, session, capture process and stable analysis workers currently satisfy MON checks.</div></div>';const items=an.top||[];E('watchdogAnomalies').innerHTML=items.map(x=>`<div class="mon-row"><span class="mon-badge">${esc(x.severity||'INFO')}</span>${esc(x.title||'Observed condition')}<br><span class="muted">${esc(x.timestamp||'')}</span></div>`).join('')||'<div class="mon-empty">No current alert or open incident.</div>';}catch(err){E('watchdogProblems').innerHTML=`<div class="mon-problem bad"><div class="title">Watchdog API unavailable</div><div class="mon-meta">${esc(err.message)}</div></div>`;}}
setInterval(()=>{const view=document.querySelector('.tab.active')?.dataset?.view;if(view==='watchdog')loadWatchdog();if(view==='investigation')loadTargets();},4000);
inject();
})();
</script>
"""
